CREATE TABLE accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,type TEXT NOT NULL,opening INTEGER NOT NULL CHECK(typeof(opening)='integer'),icon TEXT NOT NULL,color TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT COLLATE NOCASE NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('Income','Expense')),UNIQUE(name,kind));
CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL CHECK(kind IN ('Income','Expense','Transfer')),amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),account INTEGER NOT NULL REFERENCES accounts(id),destination INTEGER REFERENCES accounts(id),category INTEGER REFERENCES categories(id),day TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',demo INTEGER NOT NULL DEFAULT 0,CHECK((kind='Transfer' AND destination IS NOT NULL AND destination<>account AND category IS NULL) OR (kind<>'Transfer' AND destination IS NULL AND category IS NOT NULL)));
CREATE TABLE habits(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,icon TEXT NOT NULL,color TEXT NOT NULL,days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 127),start TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE habit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,habit INTEGER NOT NULL REFERENCES habits(id) ON DELETE CASCADE,day TEXT NOT NULL,UNIQUE(habit,day));
CREATE TABLE tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL,priority TEXT NOT NULL,day TEXT NOT NULL,completed TEXT,demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE goals(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT NOT NULL,target INTEGER NOT NULL CHECK(target>0),current INTEGER NOT NULL CHECK(current>=0),unit TEXT NOT NULL,day TEXT NOT NULL,icon TEXT NOT NULL,color TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reminders(id INTEGER PRIMARY KEY AUTOINCREMENT,habit INTEGER UNIQUE REFERENCES habits(id) ON DELETE CASCADE,task INTEGER UNIQUE REFERENCES tasks(id) ON DELETE CASCADE,minute INTEGER NOT NULL CHECK(minute BETWEEN 0 AND 1439),CHECK((habit IS NULL)<>(task IS NULL)));
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
